package bo.edu.uagrm.saludu.agenda.api;
import bo.edu.uagrm.saludu.agenda.application.AvailabilityException; import bo.edu.uagrm.saludu.identity.infrastructure.SessionPrincipal; import bo.edu.uagrm.saludu.shared.persistence.*; import java.time.LocalDate; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/medical/patients") public class MedicalHistorySearchController {private final JdbcTemplate j;private final DatabaseActorContext c;public MedicalHistorySearchController(JdbcTemplate j,DatabaseActorContext c){this.j=j;this.c=c;}@GetMapping("/{id}/search") @PreAuthorize("hasAnyRole('REVIEW_DOCTOR','SPECIALIST')") @Transactional(readOnly=true) public LegacyAvailabilityResponse<List<Map<String,Object>>> search(@PathVariable UUID id,@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to,@RequestParam(required=false) String q,@AuthenticationPrincipal SessionPrincipal p){if(q!=null&&q.trim().length()>200)throw new AvailabilityException(400,"El texto de búsqueda es demasiado largo.");c.apply(new DatabaseActor(p.id(),Set.copyOf(p.roles())));try{return LegacyAvailabilityResponse.success(j.query("select * from salud_u.buscar_historia_autorizada(?,?,?,?)",(r,n)->Map.of("id",r.getObject("id",UUID.class),"occurredAt",r.getObject("ocurrido_en"),"encounterType",r.getString("tipo_encuentro"),"status",r.getString("estado"),"chiefComplaint",r.getString("motivo"),"assessment",r.getString("evaluacion"),"specialty",r.getString("especialidad")),id,from,to,q));}catch(org.springframework.dao.DataAccessException e){String x=e.getMostSpecificCause().getMessage();throw new AvailabilityException(x!=null&&x.contains("RANGO_FECHAS_INVALIDO")?400:404,x!=null&&x.contains("RANGO_FECHAS_INVALIDO")?"El rango de fechas no es válido.":"No tienes acceso clínico a este paciente.");}}}
